import { readFileSync } from 'node:fs';
import { median, summarize, parse, weekOf, minutes } from './dashboard.mjs';
let bad = 0;
const eq = (name, got, want) => {
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (!ok) bad++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${name}${ok ? '' : `: got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`}`);
};
const csv = (...rows) => parse('id,signed_in,seen_at\n' + rows.join('\n') + '\n');

// median
eq('median of odd count', median([3, 1, 2]), 2);
eq('median of one', median([7]), 7);
eq('median of even count is mean of middle two', median([10, 20, 30, 40]), 25);
eq('median sorts numerically, not as strings', median([9, 10, 100]), 10);
eq('median sorts numerically, even count', median([5, 40, 100, 9]), 24.5);
eq('median of nothing is null', median([]), null);

// weeks start Monday
eq('Monday is its own week', weekOf('2026-03-02 08:00'), '2026-03-02');
eq('Sunday belongs to the Monday before', weekOf('2026-03-08 17:00'), '2026-03-02');
eq('Saturday belongs to the Monday before', weekOf('2026-03-07 10:00'), '2026-03-02');
eq('week across a month boundary', weekOf('2026-04-01 10:00'), '2026-03-30');

// waits are wall-clock minutes, unaffected by DST (US: 2026-03-08, EU: 2026-03-29)
eq('wait across a DST night is wall-clock', minutes('2026-03-08 01:50', '2026-03-08 03:10'), 80);

// summarize
eq('one seen visit on a Wednesday', summarize(csv('1,2026-03-04 09:00,2026-03-04 09:12')),
  [{ week: '2026-03-02', visits: 1, seen: 1, walkouts: 0, median_wait_min: 12 }]);
eq('walkouts are counted as visits, not dropped', summarize(csv(
  '1,2026-03-04 09:00,2026-03-04 09:12',
  '2,2026-03-04 09:05,',
  '3,2026-03-05 10:00,2026-03-05 10:30',
)), [{ week: '2026-03-02', visits: 3, seen: 2, walkouts: 1, median_wait_min: 21 }]);
eq('a week of only walkouts has null median', summarize(csv('1,2026-03-04 09:00,')),
  [{ week: '2026-03-02', visits: 1, seen: 0, walkouts: 1, median_wait_min: null }]);
eq('weeks print in date order', summarize(csv(
  '1,2026-03-10 09:00,2026-03-10 09:05',
  '2,2026-03-03 09:00,2026-03-03 09:07',
)).map((w) => w.week), ['2026-03-02', '2026-03-09']);
eq('CRLF input parses the same', summarize(parse('id,signed_in,seen_at\r\n1,2026-03-04 09:00,\r\n')),
  [{ week: '2026-03-02', visits: 1, seen: 0, walkouts: 1, median_wait_min: null }]);

eq('identical rows are two visits, not one', summarize(csv(
  '15,2026-02-25 10:54,2026-02-25 11:03',
  '16,2026-02-25 10:54,2026-02-25 11:03',
)), [{ week: '2026-02-23', visits: 2, seen: 2, walkouts: 0, median_wait_min: 9 }]);

// the real file: pins the corrected figures that NOTE.md quotes to the manager
eq('visits.csv weekly figures', summarize(parse(readFileSync(new URL('./visits.csv', import.meta.url), 'utf8'))), [
  { week: '2026-02-23', visits: 37, seen: 36, walkouts: 1, median_wait_min: 17 },
  { week: '2026-03-02', visits: 44, seen: 42, walkouts: 2, median_wait_min: 16.5 },
  { week: '2026-03-09', visits: 37, seen: 36, walkouts: 1, median_wait_min: 22 },
  { week: '2026-03-16', visits: 37, seen: 33, walkouts: 4, median_wait_min: 31 },
  { week: '2026-03-23', visits: 43, seen: 39, walkouts: 4, median_wait_min: 33 },
  { week: '2026-03-30', visits: 33, seen: 29, walkouts: 4, median_wait_min: 39 },
]);

process.exit(bad ? 1 : 0);
